/**
 * An {@code OPTIONAL} below a computed BIND must remain semantic native instead of creating a generic host or island.
 * The optimized bare-fragment tier may still engage, but is no longer required now that the semantic row floor covers
 * the complete root.
 */
public class LmdbNativeLeftJoinBareFragmentTest {

	private static final String EX = "http://example.com/";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.begin();
			ValueFactory vf = conn.getValueFactory();
			IRI type = org.eclipse.rdf4j.model.vocabulary.RDF.TYPE;
			IRI company = vf.createIRI(EX, "Company");
			IRI person = vf.createIRI(EX, "Person");
			IRI place = vf.createIRI(EX, "Place");
			IRI name = vf.createIRI(EX, "name");
			IRI worksAt = vf.createIRI(EX, "worksAt");
			IRI locatedIn = vf.createIRI(EX, "locatedIn");

			for (int i = 0; i < 20; i++) {
				IRI s = vf.createIRI(EX, "s" + i);
				conn.add(s, type, company);
				// a data property: object is a literal (no type)
				conn.add(s, name, vf.createLiteral("name-" + i));
				// an object property to a typed entity
				IRI colleague = vf.createIRI(EX, "person" + (i % 5));
				conn.add(s, worksAt, colleague);
				conn.add(colleague, type, person);
				// an object property to an entity that is typed only for some subjects
				IRI loc = vf.createIRI(EX, "loc" + (i % 3));
				conn.add(s, locatedIn, loc);
				if (i % 2 == 0) {
					conn.add(loc, type, place);
				}
			}
			conn.commit();
		}
	}

	@AfterEach
	public void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
	}

	@Test
	public void optionalUnderComputedExtensionRemainsSemanticNative() {
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT ?s ?type_fixed WHERE {\n"
				+ "  ?s a ex:Company.\n"
				+ "  ?s ?p ?o .\n"
				+ "  OPTIONAL { ?o a ?type }\n"
				+ "  BIND(COALESCE(STR(?type), \"DataProperties\") AS ?type_fixed)\n"
				+ "} ORDER BY ?s ?type_fixed";

		List<String> generic = genericRows(query);

		long compiledBefore = LmdbNativeAggregateCompiler.COMPILED.get();
		long hostsBefore = LmdbNativeAggregateCompiler.HOSTED_GENERIC.get();
		long islandsBefore = LmdbNativeAggregateCompiler.ISLANDS_COMPILED.get();
		List<String> nativeRows = rows(query);

		assertThat(nativeRows)
				.as("native OPTIONAL results must match the generic evaluator")
				.isEqualTo(generic);
		assertThat(LmdbNativeAggregateCompiler.COMPILED.get()).isGreaterThan(compiledBefore);
		assertThat(LmdbNativeAggregateCompiler.HOSTED_GENERIC.get()).isEqualTo(hostsBefore);
		assertThat(LmdbNativeAggregateCompiler.ISLANDS_COMPILED.get()).isEqualTo(islandsBefore);
	}

	private List<String> rows(String query) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			TupleQuery tupleQuery = conn.prepareTupleQuery(query);
			List<BindingSet> result = QueryResults.asList(tupleQuery.evaluate());
			return result.stream()
					.map(LmdbNativeLeftJoinBareFragmentTest::canonical)
					.collect(Collectors.toList());
		}
	}

	private List<String> genericRows(String query) {
		String previous = System.getProperty(NATIVE_FLAG);
		try {
			System.setProperty(NATIVE_FLAG, "false");
			return rows(query);
		} finally {
			if (previous == null) {
				System.clearProperty(NATIVE_FLAG);
			} else {
				System.setProperty(NATIVE_FLAG, previous);
			}
		}
	}

	private static String canonical(BindingSet bindings) {
		return bindings.getBindingNames()
				.stream()
				.sorted()
				.filter(name -> bindings.getValue(name) != null)
				.map(name -> name + "=" + bindings.getValue(name))
				.collect(Collectors.joining(";", "[", "]"));
	}
}
